.offers__grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--space-6); }
.offer-card {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  display: flex;
  transition: box-shadow var(--transition-base);
}
.offer-card:hover { box-shadow: var(--shadow-lg); }
.offer-card__image {
  width: 200px;
  flex-shrink: 0;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
}
.offer-card__content { padding: var(--space-6); flex: 1; display: flex; flex-direction: column; justify-content: center; }
.offer-card__title { font-size: var(--font-size-xl); font-weight: 700; margin-bottom: var(--space-2); }
.offer-card__desc { font-size: var(--font-size-sm); color: var(--color-text-secondary); margin-bottom: var(--space-4); line-height: 1.5; }

/* ===== Property Types ===== */
.property-types__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: var(--space-3);
}
.property-type {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-4) var(--space-3);
  text-align: center;
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-text);
  cursor: pointer;
  transition: all var(--transition-fast);
}
.property-type:hover { border-color: var(--color-accent); color: var(--color-accent); box-shadow: var(--shadow-sm); }

/* ===== Trip Planner Tabs ===== */
.trip-planner { background: var(--color-white); }
.tabs { display: flex; gap: var(--space-1); overflow-x: auto; padding-bottom: var(--space-2); margin-bottom: var(--space-6); scrollbar-width: thin; }
.tabs::-webkit-scrollbar { height: 4px; }
.tabs::-webkit-scrollbar-thumb { background: var(--color-border); border-radius: 2px; }
.tab {
  padding: var(--space-2) var(--space-4);
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-md);
  white-space: nowrap;
  transition: all var(--transition-fast);
  cursor: pointer;
  border: 1px solid transparent;
  background: transparent;
  min-height: 36px;
}
.tab:hover { color: var(--color-text); background: var(--color-border-light); }
.tab--active { color: var(--color-accent); background: var(--color-primary-light); border-color: var(--color-accent); font-weight: 600; }
.tab-panel { display: none; }
.tab-panel--active { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: var(--space-4); animation: fadeIn 200ms ease; }

.destination-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.destination-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.destination-card__image {
  height: 140px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
}
.destination-card__info { padding: var(--space-3) var(--space-4); }
.destination-card__name { font-size: var(--font-size-sm); font-weight: 600; margin-bottom: var(--space-1); }
.destination-card__distance { font-size: var(--font-size-xs); color: var(--color-text-secondary); }

/* ===== Unique Properties Carousel ===== */
.carousel { position: relative; }
.carousel__viewport { overflow-x: auto; scroll-snap-type: x mandatory; scroll-behavior: smooth; -webkit-overflow-scrolling: touch; scrollbar-width: none; }
.carousel__viewport::-webkit-scrollbar { display: none; }
.carousel__track { display: flex; gap: var(--space-4); padding: var(--space-2) 0; }
.carousel__nav { position: absolute; top: 50%; transform: translateY(-50%); z-index: 10; width: 44px; height: 44px; border-radius: 50%; background: var(--color-white); border: 1px solid var(--color-border); box-shadow: var(--shadow-md); display: flex; align-items: center; justify-content: center; cursor: pointer; transition: all var(--transition-fast); color: var(--color-text); }
.carousel__nav:hover { box-shadow: var(--shadow-lg); border-color: var(--color-accent); }
.carousel__nav--prev { left: -20px; }
.carousel__nav--next { right: -20px; }
.carousel__nav:disabled { opacity: 0.4; cursor: default; }

.property-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.property-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
.property-card__image {
  height: 200px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
  position: relative;
}
.property-card__badge {
  position: absolute;
  top: var(--space-3);
  left: var(--space-3);
  background: var(--color-sale);
  color: white;
  font-size: var(--font-size-xs);
  font-weight: 700;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
}
.property-card__body { padding: var(--space-4); }
.property-card__name { font-size: var(--font-size-base); font-weight: 600; margin-bottom: var(--space-1); line-height: 1.3; }
.property-card__location { font-size: var(--font-size-xs); color: var(--color-text-secondary); margin-bottom: var(--space-2); }
.property-card__rating { display: flex; align-items: center; gap: var(--space-2); margin-bottom: var(--space-3); }
.property-card__score {
  background: var(--color-primary); color: white; font-size: var(--font-size-xs); font-weight: 700;
  padding: 2px 6px; border-radius: var(--radius-sm);
}
.property-card__score--good { background: #2563EB; }
.property-card__score--excellent { background: #16A34A; }
.property-card__score--wonderful { background: #7C3AED; }
.property-card__label { font-size: var(--font-size-xs); font-weight: 600; }
.property-card__reviews { font-size: var(--font-size-xs); color: var(--color-text-muted); }
.property-card__price { display: flex; align-items: baseline; gap: var(--space-1); }
.property-card__price-current { font-size: var(--font-size-xl); font-weight: 700; color: var(--color-text); }
.property-card__price-original { font-size: var(--font-size-sm); color: var(--color-text-muted); text-decoration: line-through; }
.property-card__price-unit { font-size: var(--font-size-xs); color: var(--color-text-secondary); }

/* ===== Trending ===== */
.trending__list { display: flex; gap: var(--space-3); flex-wrap: wrap; justify-content: center; }
.trending__tag {
  padding: var(--space-2) var(--space-5);
  border: 1px solid var(--color-border);
  border-radius: 9999px;
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-text);
  transition: all var(--transition-fast);
  cursor: pointer;
  background: var(--color-white);
}
.trending__tag:hover { border-color: var(--color-accent); color: var(--color-accent); background: var(--color-primary-light); }

/* ===== Explore Destinations ===== */
.explore__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-4);
}
.explore-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.explore-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.explore-card__image {
  height: 160px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
}
.explore-card__body { padding: var(--space-4); }
.explore-card__name { font-size: var(--font-size-base); font-weight: 600; margin-bottom: var(--space-1); }
.explore-card__count { font-size: var(--font-size-sm); color: var(--color-text-secondary); }

/* ===== Weekend Deals ===== */
.deals__grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: var(--space-4); }
.deal-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.deal-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
.deal-card__image {
  height: 180px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
  position: relative;
}
.deal-card__sale-badge {
  position: absolute;
  top: var(--space-3);
  right: var(--space-3);
  background: var(--color-sale);
  color: white;
  font-size: var(--font-size-xs);
  font-weight: 700;
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-sm);
}
.deal-card__body { padding: var(--space-4); }
.deal-card__name { font-size: var(--font-size-base); font-weight: 600; margin-bottom: var(--space-1); }
.deal-card__location { font-size: var(--font-size-xs); color: var(--color-text-secondary); margin-bottom: var(--space-2); }
.deal-card__meta { display: flex; justify-content: space-between; align-items: center; margin-bottom: var(--space-2); }
.deal-card__duration { font-size: var(--font-size-xs); color: var(--color-text-secondary); }
.deal-card__pricing { display: flex; align-items: baseline; gap: var(--space-2); }
.deal-card__original { font-size: var(--font-size-sm); color: var(--color-text-muted); text-decoration: line-through; }
.deal-card__sale { font-size: var(--font-size-2xl); font-weight: 700; color: var(--color-sale); }

/* ===== Homes Guests Love ===== */
.homes__grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: var(--space-4); }

/* ===== Loyalty CTA ===== */
.loyalty-cta {
  background: var(--color-primary);
  color: var(--color-white);
  text-align: center;
}
.loyalty-cta__inner {
  max-width: 600px;
  margin: 0 auto;
}
.loyalty-cta__title { font-size: var(--font-size-3xl); font-weight: 800; color: var(--color-white); margin-bottom: var(--space-2); }
.loyalty-cta__subtitle { font-size: var(--font-size-lg); color: var(--color-gold); font-weight: 600; margin-bottom: var(--space-3); }
.loyalty-cta__body { font-size: var(--font-size-base); color: rgba(255,255,255,0.85); margin-bottom: var(--space-6); }
.loyalty-cta__actions { display: flex; gap: var(--space-3); justify-content: center; }

/* ===== Popular Links Tabs ===== */
.popular-links { background: var(--color-white); }
.popular-links__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--space-3);
}
.popular-link {
  font-size: var(--font-size-sm);
  color: var(--color-accent);
  padding: var(--space-2) 0;
  transition: all var(--transition-fast);
  cursor: pointer;
}
.popular-link:hover { color: var(--color-accent-hover); }

/* ===== Benefits (Packages) ===== */
.benefits__grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-6); }
.benefit-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  text-align: center;
  transition: all var(--transition-base);
}
.benefit-card:hover { box-shadow: var(--shadow-md); }
.benefit-card__icon { width: 48px; height: 48px; color: var(--color-accent); margin: 0 auto var(--space-4); }
.benefit-card__title { font-size: var(--font-size-lg); font-weight: 700; margin-bottom: var(--space-2); }
.benefit-card__desc { font-size: var(--font-size-sm); color: var(--color-text-secondary); }

/* ===== Radio Group (Packages) ===== */
.radio-group { display: flex; gap: var(--space-2); flex-wrap: wrap; margin-bottom: var(--space-6); justify-content: center; }
.radio-option { position: relative; }
.radio-option input { position: absolute; opacity: 0; pointer-events: none; }
.radio-option label {
  display: block;
  padding: var(--space-3) var(--space-5);
  border: 1.5px solid var(--color-border);
  border-radius: 9999px;
  font-size: var(--font-size-sm);
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.radio-option input:checked + label { background: var(--color-primary-light); border-color: var(--color-accent); color: var(--color-accent); font-weight: 600; }
.radio-option input:focus-visible + label { outline: 2px solid var(--color-accent); outline-offset: 2px; }

/* ===== Rental Companies ===== */
.companies__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: var(--space-4);
}
.company-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-lg);
  font-weight: 700;
  color: var(--color-text-secondary);
  transition: all var(--transition-base);
  cursor: pointer;
  min-height: 80px;
}
.company-card:hover { border-color: var(--color-accent); color: var(--color-accent); box-shadow: var(--shadow-sm); }

/* ===== FAQ Accordion ===== */
.accordion { max-width: 800px; margin: 0 auto; }
.accordion__item { border-bottom: 1px solid var(--color-border); }
.accordion__trigger {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-5) 0;
  font-size: var(--font-size-base);
  font-weight: 600;
  color: var(--color-text);
  text-align: left;
  cursor: pointer;
  transition: color var(--transition-fast);
  background: none;
  border: none;
}
.accordion__trigger:hover { color: var(--color-accent); }
.accordion__trigger-icon {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition-base);
  color: var(--color-text-secondary);
}
.accordion__item--open .accordion__trigger-icon { transform: rotate(180deg); }
.accordion__content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}
.accordion__item--open .accordion__content { max-height: 300px; }
.accordion__body { padding: 0 0 var(--space-5) 0; font-size: var(--font-size-sm); color: var(--color-text-secondary); line-height: 1.6; }

/* ===== Credit Card Promo ===== */
.cc-promo {
  background: linear-gradient(135deg, var(--color-primary) 0%, #002266 100%);
  border-radius: var(--radius-2xl);
  padding: var(--space-10);
  color: var(--color-white);
  display: flex;
  align-items: center;
  gap: var(--space-10);
  max-width: 900px;
  margin: 0 auto;
}
.cc-promo__icon { width: 80px; height: 80px; flex-shrink: 0; color: var(--color-gold); }
.cc-promo__title { font-size: var(--font-size-2xl); font-weight: 700; color: var(--color-white); margin-bottom: var(--space-2); }
.cc-promo__body { font-size: var(--font-size-sm); color: rgba(255,255,255,0.8); margin-bottom: var(--space-4); }

/* ===== Destinations Table ===== */
.dest-table { width: 100%; max-width: 900px; margin: 0 auto; background: var(--color-white); border-radius: var(--radius-xl); overflow: hidden; border: 1px solid var(--color-border); }
.dest-table__row {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  padding: var(--space-4) var(--space-6);
  border-bottom: 1px solid var(--color-border-light);
  transition: background var(--transition-fast);
  cursor: pointer;
}
.dest-table__row:hover { background: var(--color-border-light); }
.dest-table__row--header { font-size: var(--font-size-xs); font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--color-text-secondary); background: var(--color-border-light); cursor: default; }
.dest-table__row--header:hover { background: var(--color-border-light); }
.dest-table__cell { font-size: var(--font-size-sm); display: flex; align-items: center; }
.dest-table__cell:first-child { font-weight: 600; color: var(--color-accent); }

/* ===== Recommended / Nearby (Attractions) ===== */
.attraction-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: var(--space-4); }
.attraction-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.attraction-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.attraction-card__image {
  height: 160px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
}
.attraction-card__body { padding: var(--space-4); }
.attraction-card__title { font-size: var(--font-size-base); font-weight: 600; margin-bottom: var(--space-1); line-height: 1.4; }
.attraction-card__meta { font-size: var(--font-size-xs); color: var(--color-text-secondary); display: flex; align-items: center; gap: var(--space-1); }

/* ===== Account CTA ===== */
.account-cta {
  background: var(--color-bg);
  border-radius: var(--radius-2xl);
  padding: var(--space-10);
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
}
.account-cta__title { font-size: var(--font-size-2xl); font-weight: 700; margin-bottom: var(--space-2); }
.account-cta__subtitle { font-size: var(--font-size-base); color: var(--color-text-secondary); margin-bottom: var(--space-3); }
.account-cta__body { font-size: var(--font-size-sm); color: var(--color-text-muted); margin-bottom: var(--space-6); }
.account-cta__actions { display: flex; gap: var(--space-3); justify-content: center; }

/* ===== Things to Do Tabs ===== */
.things-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-3);
}
.thing-link {
  font-size: var(--font-size-sm);
  color: var(--color-accent);
  padding: var(--space-2) 0;
  transition: all var(--transition-fast);
  cursor: pointer;
}
.thing-link:hover { color: var(--color-accent-hover); }

/* ===== Footer ===== */
.footer {
  background: var(--color-primary);
  color: rgba(255,255,255,0.8);
  padding: var(--space-16) 0 var(--space-8);
}
.footer__grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: var(--space-8); margin-bottom: var(--space-12); }
.footer__col-title { font-size: var(--font-size-sm); font-weight: 700; color: var(--color-white); margin-bottom: var(--space-4); }
.footer__link {
  display: block;
  font-size: var(--font-size-sm);
  color: rgba(255,255,255,0.7);
  padding: var(--space-1) 0;
  transition: color var(--transition-fast);
  text-decoration: none;
}
.footer__link:hover { color: var(--color-white); }
.footer__bottom {
  border-top: 1px solid rgba(255,255,255,0.15);
  padding-top: var(--space-8);
  text-align: center;
  font-size: var(--font-size-xs);
  color: rgba(255,255,255,0.6);
}

/* ===== Animations ===== */
@keyframes fadeIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .search-form__fields { grid-template-columns: 1fr 1fr; }
  .trust-badges__grid { grid-template-columns: repeat(2, 1fr); }
  .offers__grid { grid-template-columns: 1fr; }
  .offer-card { flex-direction: column; }
  .offer-card__image { width: 100%; height: 140px; }
  .footer__grid { grid-template-columns: repeat(3, 1fr); }
  .cc-promo { flex-direction: column; text-align: center; }
  .benefits__grid { grid-template-columns: 1fr; gap: var(--space-4); }
  .dest-table__row { grid-template-columns: 2fr 1fr 1fr; padding: var(--space-3) var(--space-4); }
}

@media (max-width: 768px) {
  :root { --header-height: 56px; }
  .hero__title { font-size: var(--font-size-3xl); }
  .hero__subtitle { font-size: var(--font-size-base); }
  .section { padding: var(--space-10) 0; }
  .section__title { font-size: var(--font-size-2xl); }
  .search-form__fields { grid-template-columns: 1fr; }
  .trust-badges__grid { grid-template-columns: 1fr; gap: var(--space-4); }
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
  .carousel__nav--prev { left: 8px; }
  .carousel__nav--next { right: 8px; }
  .dest-table__row { grid-template-columns: 1fr 1fr; padding: var(--space-3); }
  .dest-table__cell:last-child { display: none; }
  .header__nav { display: none; }
  .header__mobile-toggle { display: flex; }
  .header__nav--open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--header-height);
    left: 0;
    right: 0;
    background: var(--color-primary);
    padding: var(--space-4) var(--space-6);
    gap: var(--space-1);
    box-shadow: var(--shadow-lg);
  }
  .cc-promo { padding: var(--space-6); }
  .account-cta { padding: var(--space-6); }
}

@media (max-width: 480px) {
  .container { padding: 0 var(--space-4); }
  .section__title { font-size: var(--font-size-xl); }
  .footer__grid { grid-template-columns: 1fr; gap: var(--space-6); }
  .deals__grid,
  .homes__grid,
  .attraction-grid { grid-template-columns: 1fr; }
  .explore__grid { grid-template-columns: repeat(2, 1fr); }
  .loyalty-cta__actions { flex-direction: column; align-items: center; }
  .account-cta__actions { flex-direction: column; align-items: center; }
  .radio-group { flex-direction: column; align-items: stretch; }
  .radio-option label { text-align: center; }
}

@media (min-width: 769px) {
  .header__nav { display: flex !important; }
}
