/* ===== StayQuest Design System ===== */
:root {
  /* Brand */
  --color-primary: #003B95;
  --color-primary-hover: #002A6B;
  --color-primary-light: #E8F0FE;
  --color-accent: #006CE4;
  --color-accent-hover: #0056B8;
  --color-gold: #FFB700;
  --color-gold-hover: #E6A500;
  --color-gold-light: #FFF8E1;

  /* Neutrals */
  --color-white: #FFFFFF;
  --color-bg: #F8FAFC;
  --color-surface: #FFFFFF;
  --color-border: #E2E8F0;
  --color-border-light: #F1F5F9;
  --color-text: #1E293B;
  --color-text-secondary: #64748B;
  --color-text-muted: #94A3B8;

  /* Semantic */
  --color-success: #16A34A;
  --color-success-bg: #F0FDF4;
  --color-error: #DC2626;
  --color-error-bg: #FEF2F2;
  --color-sale: #DC2626;

  /* Typography */
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 1.875rem;
  --font-size-4xl: 2.25rem;
  --font-size-5xl: 3rem;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Border Radius */
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.05);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 200ms ease;
  --transition-slow: 300ms ease;

  /* Layout */
  --max-width: 1200px;
  --header-height: 64px;
}

/* ===== Reset ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { font-size: 16px; -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }
body {
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
}
img { max-width: 100%; height: auto; display: block; }
a { color: var(--color-accent); text-decoration: none; transition: color var(--transition-fast); }
a:hover { color: var(--color-accent-hover); }
ul, ol { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
input, select { font-family: inherit; font-size: inherit; }
h1, h2, h3, h4, h5, h6 { line-height: 1.25; font-weight: 700; color: var(--color-text); }

/* ===== Focus ===== */
:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; border-radius: var(--radius-sm); }

/* ===== Reduced Motion ===== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
}

/* ===== Container ===== */
.container { width: 100%; max-width: var(--max-width); margin: 0 auto; padding: 0 var(--space-6); }

/* ===== Section ===== */
.section { padding: var(--space-16) 0; }
.section--tight { padding: var(--space-10) 0; }
.section--alt { background: var(--color-white); }
.section--brand { background: var(--color-primary); color: var(--color-white); }
.section--brand .section__title,
.section--brand .section__subtitle { color: var(--color-white); }
.section__header { text-align: center; margin-bottom: var(--space-10); }
.section__title { font-size: var(--font-size-3xl); font-weight: 700; margin-bottom: var(--space-3); color: var(--color-text); }
.section__subtitle { font-size: var(--font-size-lg); color: var(--color-text-secondary); max-width: 600px; margin: 0 auto; }

/* ===== Header / Navigation ===== */
.header {
  background: var(--color-primary);
  position: sticky;
  top: 0;
  z-index: 1000;
  height: var(--header-height);
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
}
.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}
.header__logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--font-size-xl);
  font-weight: 700;
  color: var(--color-white);
  text-decoration: none;
}
.header__logo:hover { color: var(--color-gold); }
.header__logo-icon { width: 32px; height: 32px; }
.header__nav { display: flex; align-items: center; gap: var(--space-1); }
.header__nav-link {
  padding: var(--space-2) var(--space-3);
  color: rgba(255,255,255,0.85);
  font-size: var(--font-size-sm);
  font-weight: 500;
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
  white-space: nowrap;
  text-decoration: none;
}
.header__nav-link:hover { color: var(--color-white); background: rgba(255,255,255,0.1); }
.header__nav-link--active { color: var(--color-white); background: rgba(255,255,255,0.15); font-weight: 600; }
.header__mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
  background: none;
  border: none;
  cursor: pointer;
}
.header__mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-white);
  border-radius: 1px;
  transition: transform var(--transition-base);
}

/* ===== Hero ===== */
.hero {
  background: var(--color-primary);
  color: var(--color-white);
  padding: var(--space-12) 0 var(--space-16);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 60%;
  height: 200%;
  background: radial-gradient(ellipse at center, rgba(0,107,228,0.15) 0%, transparent 70%);
  pointer-events: none;
}
.hero__content { position: relative; z-index: 1; }
.hero__title {
  font-size: var(--font-size-5xl);
  font-weight: 800;
  line-height: 1.1;
  margin-bottom: var(--space-3);
  color: var(--color-white);
}
.hero__subtitle {
  font-size: var(--font-size-xl);
  color: rgba(255,255,255,0.85);
  margin-bottom: var(--space-8);
}

/* Search Form */
.search-form {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  box-shadow: var(--shadow-xl);
}
.search-form__fields {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr auto;
  gap: var(--space-3);
  align-items: end;
}
.search-form__group { display: flex; flex-direction: column; gap: var(--space-1); }
.search-form__label {
  font-size: var(--font-size-xs);
  font-weight: 600;
  color: var(--color-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.search-form__input,
.search-form__select {
  padding: var(--space-3) var(--space-4);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  font-size: var(--font-size-sm);
  color: var(--color-text);
  background: var(--color-white);
  transition: border-color var(--transition-fast);
  min-height: 44px;
}
.search-form__input:focus,
.search-form__select:focus { border-color: var(--color-accent); outline: none; box-shadow: 0 0 0 3px rgba(0,108,228,0.1); }
.search-form__input::placeholder { color: var(--color-text-muted); }
.search-form__checkbox {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-top: var(--space-3);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  cursor: pointer;
}
.search-form__checkbox input[type="checkbox"] { width: 18px; height: 18px; accent-color: var(--color-accent); cursor: pointer; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  border-radius: var(--radius-md);
  font-size: var(--font-size-base);
  font-weight: 600;
  transition: all var(--transition-fast);
  white-space: nowrap;
  min-height: 44px;
  text-decoration: none;
}
.btn--primary { background: var(--color-accent); color: var(--color-white); }
.btn--primary:hover { background: var(--color-accent-hover); color: var(--color-white); }
.btn--gold { background: var(--color-gold); color: var(--color-primary); }
.btn--gold:hover { background: var(--color-gold-hover); }
.btn--outline { background: transparent; border: 1.5px solid var(--color-border); color: var(--color-text); }
.btn--outline:hover { border-color: var(--color-accent); color: var(--color-accent); }
.btn--white { background: var(--color-white); color: var(--color-primary); }
.btn--white:hover { background: var(--color-border-light); }
.btn--lg { padding: var(--space-4) var(--space-8); font-size: var(--font-size-lg); }
.btn--sm { padding: var(--space-2) var(--space-4); font-size: var(--font-size-sm); }
.btn--full { width: 100%; }

/* ===== Trust Badges ===== */
.trust-badges { background: var(--color-white); border-bottom: 1px solid var(--color-border); }
.trust-badges__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
}
.trust-badge { display: flex; gap: var(--space-4); align-items: flex-start; }
.trust-badge__icon {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  color: var(--color-accent);
}
.trust-badge__title { font-size: var(--font-size-sm); font-weight: 600; color: var(--color-text); margin-bottom: var(--space-1); }
.trust-badge__desc { font-size: var(--font-size-xs); color: var(--color-text-secondary); line-height: 1.4; }

/* ===== Offers ===== */
.offers__grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--space-6); }
.offer-card {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  display: flex;
  transition: box-shadow var(--transition-base);
}
.offer-card:hover { box-shadow: var(--shadow-lg); }
.offer-card__image {
  width: 200px;
  flex-shrink: 0;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
}
.offer-card__content { padding: var(--space-6); flex: 1; display: flex; flex-direction: column; justify-content: center; }
.offer-card__title { font-size: var(--font-size-xl); font-weight: 700; margin-bottom: var(--space-2); }
.offer-card__desc { font-size: var(--font-size-sm); color: var(--color-text-secondary); margin-bottom: var(--space-4); line-height: 1.5; }

/* ===== Property Types ===== */
.property-types__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: var(--space-3);
}
.property-type {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-4) var(--space-3);
  text-align: center;
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-text);
  cursor: pointer;
  transition: all var(--transition-fast);
}
.property-type:hover { border-color: var(--color-accent); color: var(--color-accent); box-shadow: var(--shadow-sm); }

/* ===== Trip Planner Tabs ===== */
.trip-planner { background: var(--color-white); }
.tabs { display: flex; gap: var(--space-1); overflow-x: auto; padding-bottom: var(--space-2); margin-bottom: var(--space-6); scrollbar-width: thin; }
.tabs::-webkit-scrollbar { height: 4px; }
.tabs::-webkit-scrollbar-thumb { background: var(--color-border); border-radius: 2px; }
.tab {
  padding: var(--space-2) var(--space-4);
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-md);
  white-space: nowrap;
  transition: all var(--transition-fast);
  cursor: pointer;
  border: 1px solid transparent;
  background: transparent;
  min-height: 36px;
}
.tab:hover { color: var(--color-text); background: var(--color-border-light); }
.tab--active { color: var(--color-accent); background: var(--color-primary-light); border-color: var(--color-accent); font-weight: 600; }
.tab-panel { display: none; }
.tab-panel--active { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: var(--space-4); animation: fadeIn 200ms ease; }

.destination-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.destination-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.destination-card__image {
  height: 140px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
}
.destination-card__info { padding: var(--space-3) var(--space-4); }
.destination-card__name { font-size: var(--font-size-sm); font-weight: 600; margin-bottom: var(--space-1); }
.destination-card__distance { font-size: var(--font-size-xs); color: var(--color-text-secondary); }

/* ===== Unique Properties Carousel ===== */
.carousel { position: relative; }
.carousel__viewport { overflow-x: auto; scroll-snap-type: x mandatory; scroll-behavior: smooth; -webkit-overflow-scrolling: touch; scrollbar-width: none; }
.carousel__viewport::-webkit-scrollbar { display: none; }
.carousel__track { display: flex; gap: var(--space-4); padding: var(--space-2) 0; }
.carousel__nav { position: absolute; top: 50%; transform: translateY(-50%); z-index: 10; width: 44px; height: 44px; border-radius: 50%; background: var(--color-white); border: 1px solid var(--color-border); box-shadow: var(--shadow-md); display: flex; align-items: center; justify-content: center; cursor: pointer; transition: all var(--transition-fast); color: var(--color-text); }
.carousel__nav:hover { box-shadow: var(--shadow-lg); border-color: var(--color-accent); }
.carousel__nav--prev { left: -20px; }
.carousel__nav--next { right: -20px; }
.carousel__nav:disabled { opacity: 0.4; cursor: default; }

.property-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.property-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
.property-card__image {
  height: 200px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
  position: relative;
}
.property-card__badge {
  position: absolute;
  top: var(--space-3);
  left: var(--space-3);
  background: var(--color-sale);
  color: white;
  font-size: var(--font-size-xs);
  font-weight: 700;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
}
.property-card__body { padding: var(--space-4); }
.property-card__name { font-size: var(--font-size-base); font-weight: 600; margin-bottom: var(--space-1); line-height: 1.3; }
.property-card__location { font-size: var(--font-size-xs); color: var(--color-text-secondary); margin-bottom: var(--space-2); }
.property-card__rating { display: flex; align-items: center; gap: var(--space-2); margin-bottom: var(--space-3); }
.property-card__score {
  background: var(--color-primary); color: white; font-size: var(--font-size-xs); font-weight: 700;
  padding: 2px 6px; border-radius: var(--radius-sm);
}
.property-card__score--good { background: #2563EB; }
.property-card__score--excellent { background: #16A34A; }
.property-card__score--wonderful { background: #7C3AED; }
.property-card__label { font-size: var(--font-size-xs); font-weight: 600; }
.property-card__reviews { font-size: var(--font-size-xs); color: var(--color-text-muted); }
.property-card__price { display: flex; align-items: baseline; gap: var(--space-1); }
.property-card__price-current { font-size: var(--font-size-xl); font-weight: 700; color: var(--color-text); }
.property-card__price-original { font-size: var(--font-size-sm); color: var(--color-text-muted); text-decoration: line-through; }
.property-card__price-unit { font-size: var(--font-size-xs); color: var(--color-text-secondary); }

/* ===== Trending ===== */
.trending__list { display: flex; gap: var(--space-3); flex-wrap: wrap; justify-content: center; }
.trending__tag {
  padding: var(--space-2) var(--space-5);
  border: 1px solid var(--color-border);
  border-radius: 9999px;
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-text);
  transition: all var(--transition-fast);
  cursor: pointer;
  background: var(--color-white);
}
.trending__tag:hover { border-color: var(--color-accent); color: var(--color-accent); background: var(--color-primary-light); }

/* ===== Explore Destinations ===== */
.explore__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-4);
}
.explore-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.explore-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.explore-card__image {
  height: 160px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
}
.explore-card__body { padding: var(--space-4); }
.explore-card__name { font-size: var(--font-size-base); font-weight: 600; margin-bottom: var(--space-1); }
.explore-card__count { font-size: var(--font-size-sm); color: var(--color-text-secondary); }

/* ===== Weekend Deals ===== */
.deals__grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: var(--space-4); }
.deal-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.deal-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
.deal-card__image {
  height: 180px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
  position: relative;
}
.deal-card__sale-badge {
  position: absolute;
  top: var(--space-3);
  right: var(--space-3);
  background: var(--color-sale);
  color: white;
  font-size: var(--font-size-xs);
  font-weight: 700;
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-sm);
}
.deal-card__body { padding: var(--space-4); }
.deal-card__name { font-size: var(--font-size-base); font-weight: 600; margin-bottom: var(--space-1); }
.deal-card__location { font-size: var(--font-size-xs); color: var(--color-text-secondary); margin-bottom: var(--space-2); }
.deal-card__meta { display: flex; justify-content: space-between; align-items: center; margin-bottom: var(--space-2); }
.deal-card__duration { font-size: var(--font-size-xs); color: var(--color-text-secondary); }
.deal-card__pricing { display: flex; align-items: baseline; gap: var(--space-2); }
.deal-card__original { font-size: var(--font-size-sm); color: var(--color-text-muted); text-decoration: line-through; }
.deal-card__sale { font-size: var(--font-size-2xl); font-weight: 700; color: var(--color-sale); }

/* ===== Homes Guests Love ===== */
.homes__grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: var(--space-4); }

/* ===== Loyalty CTA ===== */
.loyalty-cta {
  background: var(--color-primary);
  color: var(--color-white);
  text-align: center;
}
.loyalty-cta__inner {
  max-width: 600px;
  margin: 0 auto;
}
.loyalty-cta__title { font-size: var(--font-size-3xl); font-weight: 800; color: var(--color-white); margin-bottom: var(--space-2); }
.loyalty-cta__subtitle { font-size: var(--font-size-lg); color: var(--color-gold); font-weight: 600; margin-bottom: var(--space-3); }
.loyalty-cta__body { font-size: var(--font-size-base); color: rgba(255,255,255,0.85); margin-bottom: var(--space-6); }
.loyalty-cta__actions { display: flex; gap: var(--space-3); justify-content: center; }

/* ===== Popular Links Tabs ===== */
.popular-links { background: var(--color-white); }
.popular-links__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--space-3);
}
.popular-link {
  font-size: var(--font-size-sm);
  color: var(--color-accent);
  padding: var(--space-2) 0;
  transition: all var(--transition-fast);
  cursor: pointer;
}
.popular-link:hover { color: var(--color-accent-hover); }

/* ===== Benefits (Packages) ===== */
.benefits__grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-6); }
.benefit-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  text-align: center;
  transition: all var(--transition-base);
}
.benefit-card:hover { box-shadow: var(--shadow-md); }
.benefit-card__icon { width: 48px; height: 48px; color: var(--color-accent); margin: 0 auto var(--space-4); }
.benefit-card__title { font-size: var(--font-size-lg); font-weight: 700; margin-bottom: var(--space-2); }
.benefit-card__desc { font-size: var(--font-size-sm); color: var(--color-text-secondary); }

/* ===== Radio Group (Packages) ===== */
.radio-group { display: flex; gap: var(--space-2); flex-wrap: wrap; margin-bottom: var(--space-6); justify-content: center; }
.radio-option { position: relative; }
.radio-option input { position: absolute; opacity: 0; pointer-events: none; }
.radio-option label {
  display: block;
  padding: var(--space-3) var(--space-5);
  border: 1.5px solid var(--color-border);
  border-radius: 9999px;
  font-size: var(--font-size-sm);
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.radio-option input:checked + label { background: var(--color-primary-light); border-color: var(--color-accent); color: var(--color-accent); font-weight: 600; }
.radio-option input:focus-visible + label { outline: 2px solid var(--color-accent); outline-offset: 2px; }

/* ===== Rental Companies ===== */
.companies__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: var(--space-4);
}
.company-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-lg);
  font-weight: 700;
  color: var(--color-text-secondary);
  transition: all var(--transition-base);
  cursor: pointer;
  min-height: 80px;
}
.company-card:hover { border-color: var(--color-accent); color: var(--color-accent); box-shadow: var(--shadow-sm); }

/* ===== FAQ Accordion ===== */
.accordion { max-width: 800px; margin: 0 auto; }
.accordion__item { border-bottom: 1px solid var(--color-border); }
.accordion__trigger {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-5) 0;
  font-size: var(--font-size-base);
  font-weight: 600;
  color: var(--color-text);
  text-align: left;
  cursor: pointer;
  transition: color var(--transition-fast);
  background: none;
  border: none;
}
.accordion__trigger:hover { color: var(--color-accent); }
.accordion__trigger-icon {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition-base);
  color: var(--color-text-secondary);
}
.accordion__item--open .accordion__trigger-icon { transform: rotate(180deg); }
.accordion__content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}
.accordion__item--open .accordion__content { max-height: 300px; }
.accordion__body { padding: 0 0 var(--space-5) 0; font-size: var(--font-size-sm); color: var(--color-text-secondary); line-height: 1.6; }

/* ===== Credit Card Promo ===== */
.cc-promo {
  background: linear-gradient(135deg, var(--color-primary) 0%, #002266 100%);
  border-radius: var(--radius-2xl);
  padding: var(--space-10);
  color: var(--color-white);
  display: flex;
  align-items: center;
  gap: var(--space-10);
  max-width: 900px;
  margin: 0 auto;
}
.cc-promo__icon { width: 80px; height: 80px; flex-shrink: 0; color: var(--color-gold); }
.cc-promo__title { font-size: var(--font-size-2xl); font-weight: 700; color: var(--color-white); margin-bottom: var(--space-2); }
.cc-promo__body { font-size: var(--font-size-sm); color: rgba(255,255,255,0.8); margin-bottom: var(--space-4); }

/* ===== Destinations Table ===== */
.dest-table { width: 100%; max-width: 900px; margin: 0 auto; background: var(--color-white); border-radius: var(--radius-xl); overflow: hidden; border: 1px solid var(--color-border); }
.dest-table__row {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  padding: var(--space-4) var(--space-6);
  border-bottom: 1px solid var(--color-border-light);
  transition: background var(--transition-fast);
  cursor: pointer;
}
.dest-table__row:hover { background: var(--color-border-light); }
.dest-table__row--header { font-size: var(--font-size-xs); font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--color-text-secondary); background: var(--color-border-light); cursor: default; }
.dest-table__row--header:hover { background: var(--color-border-light); }
.dest-table__cell { font-size: var(--font-size-sm); display: flex; align-items: center; }
.dest-table__cell:first-child { font-weight: 600; color: var(--color-accent); }

/* ===== Recommended / Nearby (Attractions) ===== */
.attraction-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: var(--space-4); }
.attraction-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.attraction-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.attraction-card__image {
  height: 160px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
}
.attraction-card__body { padding: var(--space-4); }
.attraction-card__title { font-size: var(--font-size-base); font-weight: 600; margin-bottom: var(--space-1); line-height: 1.4; }
.attraction-card__meta { font-size: var(--font-size-xs); color: var(--color-text-secondary); display: flex; align-items: center; gap: var(--space-1); }

/* ===== Account CTA ===== */
.account-cta {
  background: var(--color-bg);
  border-radius: var(--radius-2xl);
  padding: var(--space-10);
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
}
.account-cta__title { font-size: var(--font-size-2xl); font-weight: 700; margin-bottom: var(--space-2); }
.account-cta__subtitle { font-size: var(--font-size-base); color: var(--color-text-secondary); margin-bottom: var(--space-3); }
.account-cta__body { font-size: var(--font-size-sm); color: var(--color-text-muted); margin-bottom: var(--space-6); }
.account-cta__actions { display: flex; gap: var(--space-3); justify-content: center; }

/* ===== Things to Do Tabs ===== */
.things-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-3);
}
.thing-link {
  font-size: var(--font-size-sm);
  color: var(--color-accent);
  padding: var(--space-2) 0;
  transition: all var(--transition-fast);
  cursor: pointer;
}
.thing-link:hover { color: var(--color-accent-hover); }

/* ===== Footer ===== */
.footer {
  background: var(--color-primary);
  color: rgba(255,255,255,0.8);
  padding: var(--space-16) 0 var(--space-8);
}
.footer__grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: var(--space-8); margin-bottom: var(--space-12); }
.footer__col-title { font-size: var(--font-size-sm); font-weight: 700; color: var(--color-white); margin-bottom: var(--space-4); }
.footer__link {
  display: block;
  font-size: var(--font-size-sm);
  color: rgba(255,255,255,0.7);
  padding: var(--space-1) 0;
  transition: color var(--transition-fast);
  text-decoration: none;
}
.footer__link:hover { color: var(--color-white); }
.footer__bottom {
  border-top: 1px solid rgba(255,255,255,0.15);
  padding-top: var(--space-8);
  text-align: center;
  font-size: var(--font-size-xs);
  color: rgba(255,255,255,0.6);
}

/* ===== Animations ===== */
@keyframes fadeIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .search-form__fields { grid-template-columns: 1fr 1fr; }
  .trust-badges__grid { grid-template-columns: repeat(2, 1fr); }
  .offers__grid { grid-template-columns: 1fr; }
  .offer-card { flex-direction: column; }
  .offer-card__image { width: 100%; height: 140px; }
  .footer__grid { grid-template-columns: repeat(3, 1fr); }
  .cc-promo { flex-direction: column; text-align: center; }
  .benefits__grid { grid-template-columns: 1fr; gap: var(--space-4); }
  .dest-table__row { grid-template-columns: 2fr 1fr 1fr; padding: var(--space-3) var(--space-4); }
}

@media (max-width: 768px) {
  :root { --header-height: 56px; }
  .hero__title { font-size: var(--font-size-3xl); }
  .hero__subtitle { font-size: var(--font-size-base); }
  .section { padding: var(--space-10) 0; }
  .section__title { font-size: var(--font-size-2xl); }
  .search-form__fields { grid-template-columns: 1fr; }
  .trust-badges__grid { grid-template-columns: 1fr; gap: var(--space-4); }
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
  .carousel__nav--prev { left: 8px; }
  .carousel__nav--next { right: 8px; }
  .dest-table__row { grid-template-columns: 1fr 1fr; padding: var(--space-3); }
  .dest-table__cell:last-child { display: none; }
  .header__nav { display: none; }
  .header__mobile-toggle { display: flex; }
  .header__nav--open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--header-height);
    left: 0;
    right: 0;
    background: var(--color-primary);
    padding: var(--space-4) var(--space-6);
    gap: var(--space-1);
    box-shadow: var(--shadow-lg);
  }
  .cc-promo { padding: var(--space-6); }
  .account-cta { padding: var(--space-6); }
}

@media (max-width: 480px) {
  .container { padding: 0 var(--space-4); }
  .section__title { font-size: var(--font-size-xl); }
  .footer__grid { grid-template-columns: 1fr; gap: var(--space-6); }
  .deals__grid,
  .homes__grid,
  .attraction-grid { grid-template-columns: 1fr; }
  .explore__grid { grid-template-columns: repeat(2, 1fr); }
  .loyalty-cta__actions { flex-direction: column; align-items: center; }
  .account-cta__actions { flex-direction: column; align-items: center; }
  .radio-group { flex-direction: column; align-items: stretch; }
  .radio-option label { text-align: center; }
}

@media (min-width: 769px) {
  .header__nav { display: flex !important; }
}

/* ===== StayQuest Design System ===== */
:root {
  /* Brand */
  --color-primary: #003B95;
  --color-primary-hover: #002A6B;
  --color-primary-light: #E8F0FE;
  --color-accent: #006CE4;
  --color-accent-hover: #0056B8;
  --color-gold: #FFB700;
  --color-gold-hover: #E6A500;
  --color-gold-light: #FFF8E1;

  /* Neutrals */
  --color-white: #FFFFFF;
  --color-bg: #F8FAFC;
  --color-surface: #FFFFFF;
  --color-border: #E2E8F0;
  --color-border-light: #F1F5F9;
  --color-text: #1E293B;
  --color-text-secondary: #64748B;
  --color-text-muted: #94A3B8;

  /* Semantic */
  --color-success: #16A34A;
  --color-success-bg: #F0FDF4;
  --color-error: #DC2626;
  --color-error-bg: #FEF2F2;
  --color-sale: #DC2626;

  /* Typography */
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 1.875rem;
  --font-size-4xl: 2.25rem;
  --font-size-5xl: 3rem;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Border Radius */
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.05);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 200ms ease;
  --transition-slow: 300ms ease;

  /* Layout */
  --max-width: 1200px;
  --header-height: 64px;
}

/* ===== Reset ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { font-size: 16px; -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }
body {
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
}
img { max-width: 100%; height: auto; display: block; }
a { color: var(--color-accent); text-decoration: none; transition: color var(--transition-fast); }
a:hover { color: var(--color-accent-hover); }
ul, ol { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
input, select { font-family: inherit; font-size: inherit; }
h1, h2, h3, h4, h5, h6 { line-height: 1.25; font-weight: 700; color: var(--color-text); }

/* ===== Focus ===== */
:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; border-radius: var(--radius-sm); }

/* ===== Reduced Motion ===== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
}

/* ===== Container ===== */
.container { width: 100%; max-width: var(--max-width); margin: 0 auto; padding: 0 var(--space-6); }

/* ===== Section ===== */
.section { padding: var(--space-16) 0; }
.section--tight { padding: var(--space-10) 0; }
.section--alt { background: var(--color-white); }
.section--brand { background: var(--color-primary); color: var(--color-white); }
.section--brand .section__title,
.section--brand .section__subtitle { color: var(--color-white); }
.section__header { text-align: center; margin-bottom: var(--space-10); }
.section__title { font-size: var(--font-size-3xl); font-weight: 700; margin-bottom: var(--space-3); color: var(--color-text); }
.section__subtitle { font-size: var(--font-size-lg); color: var(--color-text-secondary); max-width: 600px; margin: 0 auto; }

/* ===== Header / Navigation ===== */
.header {
  background: var(--color-primary);
  position: sticky;
  top: 0;
  z-index: 1000;
  height: var(--header-height);
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
}
.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}
.header__logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--font-size-xl);
  font-weight: 700;
  color: var(--color-white);
  text-decoration: none;
}
.header__logo:hover { color: var(--color-gold); }
.header__logo-icon { width: 32px; height: 32px; }
.header__nav { display: flex; align-items: center; gap: var(--space-1); }
.header__nav-link {
  padding: var(--space-2) var(--space-3);
  color: rgba(255,255,255,0.85);
  font-size: var(--font-size-sm);
  font-weight: 500;
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
  white-space: nowrap;
  text-decoration: none;
}
.header__nav-link:hover { color: var(--color-white); background: rgba(255,255,255,0.1); }
.header__nav-link--active { color: var(--color-white); background: rgba(255,255,255,0.15); font-weight: 600; }
.header__mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
  background: none;
  border: none;
  cursor: pointer;
}
.header__mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-white);
  border-radius: 1px;
  transition: transform var(--transition-base);
}

/* ===== Hero ===== */
.hero {
  background: var(--color-primary);
  color: var(--color-white);
  padding: var(--space-12) 0 var(--space-16);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 60%;
  height: 200%;
  background: radial-gradient(ellipse at center, rgba(0,107,228,0.15) 0%, transparent 70%);
  pointer-events: none;
}
.hero__content { position: relative; z-index: 1; }
.hero__title {
  font-size: var(--font-size-5xl);
  font-weight: 800;
  line-height: 1.1;
  margin-bottom: var(--space-3);
  color: var(--color-white);
}
.hero__subtitle {
  font-size: var(--font-size-xl);
  color: rgba(255,255,255,0.85);
  margin-bottom: var(--space-8);
}

/* Search Form */
.search-form {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  box-shadow: var(--shadow-xl);
}
.search-form__fields {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr auto;
  gap: var(--space-3);
  align-items: end;
}
.search-form__group { display: flex; flex-direction: column; gap: var(--space-1); }
.search-form__label {
  font-size: var(--font-size-xs);
  font-weight: 600;
  color: var(--color-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.search-form__input,
.search-form__select {
  padding: var(--space-3) var(--space-4);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  font-size: var(--font-size-sm);
  color: var(--color-text);
  background: var(--color-white);
  transition: border-color var(--transition-fast);
  min-height: 44px;
}
.search-form__input:focus,
.search-form__select:focus { border-color: var(--color-accent); outline: none; box-shadow: 0 0 0 3px rgba(0,108,228,0.1); }
.search-form__input::placeholder { color: var(--color-text-muted); }
.search-form__checkbox {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-top: var(--space-3);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  cursor: pointer;
}
.search-form__checkbox input[type="checkbox"] { width: 18px; height: 18px; accent-color: var(--color-accent); cursor: pointer; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  border-radius: var(--radius-md);
  font-size: var(--font-size-base);
  font-weight: 600;
  transition: all var(--transition-fast);
  white-space: nowrap;
  min-height: 44px;
  text-decoration: none;
}
.btn--primary { background: var(--color-accent); color: var(--color-white); }
.btn--primary:hover { background: var(--color-accent-hover); color: var(--color-white); }
.btn--gold { background: var(--color-gold); color: var(--color-primary); }
.btn--gold:hover { background: var(--color-gold-hover); }
.btn--outline { background: transparent; border: 1.5px solid var(--color-border); color: var(--color-text); }
.btn--outline:hover { border-color: var(--color-accent); color: var(--color-accent); }
.btn--white { background: var(--color-white); color: var(--color-primary); }
.btn--white:hover { background: var(--color-border-light); }
.btn--lg { padding: var(--space-4) var(--space-8); font-size: var(--font-size-lg); }
.btn--sm { padding: var(--space-2) var(--space-4); font-size: var(--font-size-sm); }
.btn--full { width: 100%; }

/* ===== Trust Badges ===== */
.trust-badges { background: var(--color-white); border-bottom: 1px solid var(--color-border); }
.trust-badges__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
}
.trust-badge { display: flex; gap: var(--space-4); align-items: flex-start; }
.trust-badge__icon {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  color: var(--color-accent);
}
.trust-badge__title { font-size: var(--font-size-sm); font-weight: 600; color: var(--color-text); margin-bottom: var(--space-1); }
.trust-badge__desc { font-size: var(--font-size-xs); color: var(--color-text-secondary); line-height: 1.4; }

/* ===== Offers ===== */
.offers__grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--space-6); }
.offer-card {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  display: flex;
  transition: box-shadow var(--transition-base);
}
.offer-card:hover { box-shadow: var(--shadow-lg); }
.offer-card__image {
  width: 200px;
  flex-shrink: 0;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
}
.offer-card__content { padding: var(--space-6); flex: 1; display: flex; flex-direction: column; justify-content: center; }
.offer-card__title { font-size: var(--font-size-xl); font-weight: 700; margin-bottom: var(--space-2); }
.offer-card__desc { font-size: var(--font-size-sm); color: var(--color-text-secondary); margin-bottom: var(--space-4); line-height: 1.5; }

/* ===== Property Types ===== */
.property-types__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: var(--space-3);
}
.property-type {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-4) var(--space-3);
  text-align: center;
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-text);
  cursor: pointer;
  transition: all var(--transition-fast);
}
.property-type:hover { border-color: var(--color-accent); color: var(--color-accent); box-shadow: var(--shadow-sm); }

/* ===== Trip Planner Tabs ===== */
.trip-planner { background: var(--color-white); }
.tabs { display: flex; gap: var(--space-1); overflow-x: auto; padding-bottom: var(--space-2); margin-bottom: var(--space-6); scrollbar-width: thin; }
.tabs::-webkit-scrollbar { height: 4px; }
.tabs::-webkit-scrollbar-thumb { background: var(--color-border); border-radius: 2px; }
.tab {
  padding: var(--space-2) var(--space-4);
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-md);
  white-space: nowrap;
  transition: all var(--transition-fast);
  cursor: pointer;
  border: 1px solid transparent;
  background: transparent;
  min-height: 36px;
}
.tab:hover { color: var(--color-text); background: var(--color-border-light); }
.tab--active { color: var(--color-accent); background: var(--color-primary-light); border-color: var(--color-accent); font-weight: 600; }
.tab-panel { display: none; }
.tab-panel--active { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: var(--space-4); animation: fadeIn 200ms ease; }

.destination-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.destination-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.destination-card__image {
  height: 140px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
}
.destination-card__info { padding: var(--space-3) var(--space-4); }
.destination-card__name { font-size: var(--font-size-sm); font-weight: 600; margin-bottom: var(--space-1); }
.destination-card__distance { font-size: var(--font-size-xs); color: var(--color-text-secondary); }

/* ===== Unique Properties Carousel ===== */
.carousel { position: relative; }
.carousel__viewport { overflow-x: auto; scroll-snap-type: x mandatory; scroll-behavior: smooth; -webkit-overflow-scrolling: touch; scrollbar-width: none; }
.carousel__viewport::-webkit-scrollbar { display: none; }
.carousel__track { display: flex; gap: var(--space-4); padding: var(--space-2) 0; }
.carousel__nav { position: absolute; top: 50%; transform: translateY(-50%); z-index: 10; width: 44px; height: 44px; border-radius: 50%; background: var(--color-white); border: 1px solid var(--color-border); box-shadow: var(--shadow-md); display: flex; align-items: center; justify-content: center; cursor: pointer; transition: all var(--transition-fast); color: var(--color-text); }
.carousel__nav:hover { box-shadow: var(--shadow-lg); border-color: var(--color-accent); }
.carousel__nav--prev { left: -20px; }
.carousel__nav--next { right: -20px; }
.carousel__nav:disabled { opacity: 0.4; cursor: default; }

.property-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.property-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
.property-card__image {
  height: 200px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
  position: relative;
}
.property-card__badge {
  position: absolute;
  top: var(--space-3);
  left: var(--space-3);
  background: var(--color-sale);
  color: white;
  font-size: var(--font-size-xs);
  font-weight: 700;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
}
.property-card__body { padding: var(--space-4); }
.property-card__name { font-size: var(--font-size-base); font-weight: 600; margin-bottom: var(--space-1); line-height: 1.3; }
.property-card__location { font-size: var(--font-size-xs); color: var(--color-text-secondary); margin-bottom: var(--space-2); }
.property-card__rating { display: flex; align-items: center; gap: var(--space-2); margin-bottom: var(--space-3); }
.property-card__score {
  background: var(--color-primary); color: white; font-size: var(--font-size-xs); font-weight: 700;
  padding: 2px 6px; border-radius: var(--radius-sm);
}
.property-card__score--good { background: #2563EB; }
.property-card__score--excellent { background: #16A34A; }
.property-card__score--wonderful { background: #7C3AED; }
.property-card__label { font-size: var(--font-size-xs); font-weight: 600; }
.property-card__reviews { font-size: var(--font-size-xs); color: var(--color-text-muted); }
.property-card__price { display: flex; align-items: baseline; gap: var(--space-1); }
.property-card__price-current { font-size: var(--font-size-xl); font-weight: 700; color: var(--color-text); }
.property-card__price-original { font-size: var(--font-size-sm); color: var(--color-text-muted); text-decoration: line-through; }
.property-card__price-unit { font-size: var(--font-size-xs); color: var(--color-text-secondary); }

/* ===== Trending ===== */
.trending__list { display: flex; gap: var(--space-3); flex-wrap: wrap; justify-content: center; }
.trending__tag {
  padding: var(--space-2) var(--space-5);
  border: 1px solid var(--color-border);
  border-radius: 9999px;
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-text);
  transition: all var(--transition-fast);
  cursor: pointer;
  background: var(--color-white);
}
.trending__tag:hover { border-color: var(--color-accent); color: var(--color-accent); background: var(--color-primary-light); }

/* ===== Explore Destinations ===== */
.explore__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-4);
}
.explore-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.explore-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.explore-card__image {
  height: 160px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
}
.explore-card__body { padding: var(--space-4); }
.explore-card__name { font-size: var(--font-size-base); font-weight: 600; margin-bottom: var(--space-1); }
.explore-card__count { font-size: var(--font-size-sm); color: var(--color-text-secondary); }

/* ===== Weekend Deals ===== */
.deals__grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: var(--space-4); }
.deal-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.deal-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
.deal-card__image {
  height: 180px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
  position: relative;
}
.deal-card__sale-badge {
  position: absolute;
  top: var(--space-3);
  right: var(--space-3);
  background: var(--color-sale);
  color: white;
  font-size: var(--font-size-xs);
  font-weight: 700;
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-sm);
}
.deal-card__body { padding: var(--space-4); }
.deal-card__name { font-size: var(--font-size-base); font-weight: 600; margin-bottom: var(--space-1); }
.deal-card__location { font-size: var(--font-size-xs); color: var(--color-text-secondary); margin-bottom: var(--space-2); }
.deal-card__meta { display: flex; justify-content: space-between; align-items: center; margin-bottom: var(--space-2); }
.deal-card__duration { font-size: var(--font-size-xs); color: var(--color-text-secondary); }
.deal-card__pricing { display: flex; align-items: baseline; gap: var(--space-2); }
.deal-card__original { font-size: var(--font-size-sm); color: var(--color-text-muted); text-decoration: line-through; }
.deal-card__sale { font-size: var(--font-size-2xl); font-weight: 700; color: var(--color-sale); }

/* ===== Homes Guests Love ===== */
.homes__grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: var(--space-4); }

/* ===== Loyalty CTA ===== */
.loyalty-cta {
  background: var(--color-primary);
  color: var(--color-white);
  text-align: center;
}
.loyalty-cta__inner {
  max-width: 600px;
  margin: 0 auto;
}
.loyalty-cta__title { font-size: var(--font-size-3xl); font-weight: 800; color: var(--color-white); margin-bottom: var(--space-2); }
.loyalty-cta__subtitle { font-size: var(--font-size-lg); color: var(--color-gold); font-weight: 600; margin-bottom: var(--space-3); }
.loyalty-cta__body { font-size: var(--font-size-base); color: rgba(255,255,255,0.85); margin-bottom: var(--space-6); }
.loyalty-cta__actions { display: flex; gap: var(--space-3); justify-content: center; }

/* ===== Popular Links Tabs ===== */
.popular-links { background: var(--color-white); }
.popular-links__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--space-3);
}
.popular-link {
  font-size: var(--font-size-sm);
  color: var(--color-accent);
  padding: var(--space-2) 0;
  transition: all var(--transition-fast);
  cursor: pointer;
}
.popular-link:hover { color: var(--color-accent-hover); }

/* ===== Benefits (Packages) ===== */
.benefits__grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-6); }
.benefit-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  text-align: center;
  transition: all var(--transition-base);
}
.benefit-card:hover { box-shadow: var(--shadow-md); }
.benefit-card__icon { width: 48px; height: 48px; color: var(--color-accent); margin: 0 auto var(--space-4); }
.benefit-card__title { font-size: var(--font-size-lg); font-weight: 700; margin-bottom: var(--space-2); }
.benefit-card__desc { font-size: var(--font-size-sm); color: var(--color-text-secondary); }

/* ===== Radio Group (Packages) ===== */
.radio-group { display: flex; gap: var(--space-2); flex-wrap: wrap; margin-bottom: var(--space-6); justify-content: center; }
.radio-option { position: relative; }
.radio-option input { position: absolute; opacity: 0; pointer-events: none; }
.radio-option label {
  display: block;
  padding: var(--space-3) var(--space-5);
  border: 1.5px solid var(--color-border);
  border-radius: 9999px;
  font-size: var(--font-size-sm);
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.radio-option input:checked + label { background: var(--color-primary-light); border-color: var(--color-accent); color: var(--color-accent); font-weight: 600; }
.radio-option input:focus-visible + label { outline: 2px solid var(--color-accent); outline-offset: 2px; }

/* ===== Rental Companies ===== */
.companies__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: var(--space-4);
}
.company-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-lg);
  font-weight: 700;
  color: var(--color-text-secondary);
  transition: all var(--transition-base);
  cursor: pointer;
  min-height: 80px;
}
.company-card:hover { border-color: var(--color-accent); color: var(--color-accent); box-shadow: var(--shadow-sm); }

/* ===== FAQ Accordion ===== */
.accordion { max-width: 800px; margin: 0 auto; }
.accordion__item { border-bottom: 1px solid var(--color-border); }
.accordion__trigger {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-5) 0;
  font-size: var(--font-size-base);
  font-weight: 600;
  color: var(--color-text);
  text-align: left;
  cursor: pointer;
  transition: color var(--transition-fast);
  background: none;
  border: none;
}
.accordion__trigger:hover { color: var(--color-accent); }
.accordion__trigger-icon {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition-base);
  color: var(--color-text-secondary);
}
.accordion__item--open .accordion__trigger-icon { transform: rotate(180deg); }
.accordion__content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}
.accordion__item--open .accordion__content { max-height: 300px; }
.accordion__body { padding: 0 0 var(--space-5) 0; font-size: var(--font-size-sm); color: var(--color-text-secondary); line-height: 1.6; }

/* ===== Credit Card Promo ===== */
.cc-promo {
  background: linear-gradient(135deg, var(--color-primary) 0%, #002266 100%);
  border-radius: var(--radius-2xl);
  padding: var(--space-10);
  color: var(--color-white);
  display: flex;
  align-items: center;
  gap: var(--space-10);
  max-width: 900px;
  margin: 0 auto;
}
.cc-promo__icon { width: 80px; height: 80px; flex-shrink: 0; color: var(--color-gold); }
.cc-promo__title { font-size: var(--font-size-2xl); font-weight: 700; color: var(--color-white); margin-bottom: var(--space-2); }
.cc-promo__body { font-size: var(--font-size-sm); color: rgba(255,255,255,0.8); margin-bottom: var(--space-4); }

/* ===== Destinations Table ===== */
.dest-table { width: 100%; max-width: 900px; margin: 0 auto; background: var(--color-white); border-radius: var(--radius-xl); overflow: hidden; border: 1px solid var(--color-border); }
.dest-table__row {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  padding: var(--space-4) var(--space-6);
  border-bottom: 1px solid var(--color-border-light);
  transition: background var(--transition-fast);
  cursor: pointer;
}
.dest-table__row:hover { background: var(--color-border-light); }
.dest-table__row--header { font-size: var(--font-size-xs); font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--color-text-secondary); background: var(--color-border-light); cursor: default; }
.dest-table__row--header:hover { background: var(--color-border-light); }
.dest-table__cell { font-size: var(--font-size-sm); display: flex; align-items: center; }
.dest-table__cell:first-child { font-weight: 600; color: var(--color-accent); }

/* ===== Recommended / Nearby (Attractions) ===== */
.attraction-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: var(--space-4); }
.attraction-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.attraction-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.attraction-card__image {
  height: 160px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
}
.attraction-card__body { padding: var(--space-4); }
.attraction-card__title { font-size: var(--font-size-base); font-weight: 600; margin-bottom: var(--space-1); line-height: 1.4; }
.attraction-card__meta { font-size: var(--font-size-xs); color: var(--color-text-secondary); display: flex; align-items: center; gap: var(--space-1); }

/* ===== Account CTA ===== */
.account-cta {
  background: var(--color-bg);
  border-radius: var(--radius-2xl);
  padding: var(--space-10);
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
}
.account-cta__title { font-size: var(--font-size-2xl); font-weight: 700; margin-bottom: var(--space-2); }
.account-cta__subtitle { font-size: var(--font-size-base); color: var(--color-text-secondary); margin-bottom: var(--space-3); }
.account-cta__body { font-size: var(--font-size-sm); color: var(--color-text-muted); margin-bottom: var(--space-6); }
.account-cta__actions { display: flex; gap: var(--space-3); justify-content: center; }

/* ===== Things to Do Tabs ===== */
.things-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-3);
}
.thing-link {
  font-size: var(--font-size-sm);
  color: var(--color-accent);
  padding: var(--space-2) 0;
  transition: all var(--transition-fast);
  cursor: pointer;
}
.thing-link:hover { color: var(--color-accent-hover); }

/* ===== Footer ===== */
.footer {
  background: var(--color-primary);
  color: rgba(255,255,255,0.8);
  padding: var(--space-16) 0 var(--space-8);
}
.footer__grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: var(--space-8); margin-bottom: var(--space-12); }
.footer__col-title { font-size: var(--font-size-sm); font-weight: 700; color: var(--color-white); margin-bottom: var(--space-4); }
.footer__link {
  display: block;
  font-size: var(--font-size-sm);
  color: rgba(255,255,255,0.7);
  padding: var(--space-1) 0;
  transition: color var(--transition-fast);
  text-decoration: none;
}
.footer__link:hover { color: var(--color-white); }
.footer__bottom {
  border-top: 1px solid rgba(255,255,255,0.15);
  padding-top: var(--space-8);
  text-align: center;
  font-size: var(--font-size-xs);
  color: rgba(255,255,255,0.6);
}

/* ===== Animations ===== */
@keyframes fadeIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .search-form__fields { grid-template-columns: 1fr 1fr; }
  .trust-badges__grid { grid-template-columns: repeat(2, 1fr); }
  .offers__grid { grid-template-columns: 1fr; }
  .offer-card { flex-direction: column; }
  .offer-card__image { width: 100%; height: 140px; }
  .footer__grid { grid-template-columns: repeat(3, 1fr); }
  .cc-promo { flex-direction: column; text-align: center; }
  .benefits__grid { grid-template-columns: 1fr; gap: var(--space-4); }
  .dest-table__row { grid-template-columns: 2fr 1fr 1fr; padding: var(--space-3) var(--space-4); }
}

@media (max-width: 768px) {
  :root { --header-height: 56px; }
  .hero__title { font-size: var(--font-size-3xl); }
  .hero__subtitle { font-size: var(--font-size-base); }
  .section { padding: var(--space-10) 0; }
  .section__title { font-size: var(--font-size-2xl); }
  .search-form__fields { grid-template-columns: 1fr; }
  .trust-badges__grid { grid-template-columns: 1fr; gap: var(--space-4); }
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
  .carousel__nav--prev { left: 8px; }
  .carousel__nav--next { right: 8px; }
  .dest-table__row { grid-template-columns: 1fr 1fr; padding: var(--space-3); }
  .dest-table__cell:last-child { display: none; }
  .header__nav { display: none; }
  .header__mobile-toggle { display: flex; }
  .header__nav--open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--header-height);
    left: 0;
    right: 0;
    background: var(--color-primary);
    padding: var(--space-4) var(--space-6);
    gap: var(--space-1);
    box-shadow: var(--shadow-lg);
  }
  .cc-promo { padding: var(--space-6); }
  .account-cta { padding: var(--space-6); }
}

@media (max-width: 480px) {
  .container { padding: 0 var(--space-4); }
  .section__title { font-size: var(--font-size-xl); }
  .footer__grid { grid-template-columns: 1fr; gap: var(--space-6); }
  .deals__grid,
  .homes__grid,
  .attraction-grid { grid-template-columns: 1fr; }
  .explore__grid { grid-template-columns: repeat(2, 1fr); }
  .loyalty-cta__actions { flex-direction: column; align-items: center; }
  .account-cta__actions { flex-direction: column; align-items: center; }
  .radio-group { flex-direction: column; align-items: stretch; }
  .radio-option label { text-align: center; }
}

@media (min-width: 769px) {
  .header__nav { display: flex !important; }
}

raw_arguments.content:
/* ===== StayQuest Design System ===== */
:root {
  /* Brand */
  --color-primary: #003B95;
  --color-primary-hover: #002A6B;
  --color-primary-light: #E8F0FE;
  --color-accent: #006CE4;
  --color-accent-hover: #0056B8;
  --color-gold: #FFB700;
  --color-gold-hover: #E6A500;
  --color-gold-light: #FFF8E1;

  /* Neutrals */
  --color-white: #FFFFFF;
  --color-bg: #F8FAFC;
  --color-surface: #FFFFFF;
  --color-border: #E2E8F0;
  --color-border-light: #F1F5F9;
  --color-text: #1E293B;
  --color-text-secondary: #64748B;
  --color-text-muted: #94A3B8;

  /* Semantic */
  --color-success: #16A34A;
  --color-success-bg: #F0FDF4;
  --color-error: #DC2626;
  --color-error-bg: #FEF2F2;
  --color-sale: #DC2626;

  /* Typography */
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 1.875rem;
  --font-size-4xl: 2.25rem;
  --font-size-5xl: 3rem;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Border Radius */
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.05);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 200ms ease;
  --transition-slow: 300ms ease;

  /* Layout */
  --max-width: 1200px;
  --header-height: 64px;
}

/* ===== Reset ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { font-size: 16px; -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }
body {
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
}
img { max-width: 100%; height: auto; display: block; }
a { color: var(--color-accent); text-decoration: none; transition: color var(--transition-fast); }
a:hover { color: var(--color-accent-hover); }
ul, ol { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
input, select { font-family: inherit; font-size: inherit; }
h1, h2, h3, h4, h5, h6 { line-height: 1.25; font-weight: 700; color: var(--color-text); }

/* ===== Focus ===== */
:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; border-radius: var(--radius-sm); }

/* ===== Reduced Motion ===== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
}

/* ===== Container ===== */
.container { width: 100%; max-width: var(--max-width); margin: 0 auto; padding: 0 var(--space-6); }

/* ===== Section ===== */
.section { padding: var(--space-16) 0; }
.section--tight { padding: var(--space-10) 0; }
.section--alt { background: var(--color-white); }
.section--brand { background: var(--color-primary); color: var(--color-white); }
.section--brand .section__title,
.section--brand .section__subtitle { color: var(--color-white); }
.section__header { text-align: center; margin-bottom: var(--space-10); }
.section__title { font-size: var(--font-size-3xl); font-weight: 700; margin-bottom: var(--space-3); color: var(--color-text); }
.section__subtitle { font-size: var(--font-size-lg); color: var(--color-text-secondary); max-width: 600px; margin: 0 auto; }

/* ===== Header / Navigation ===== */
.header {
  background: var(--color-primary);
  position: sticky;
  top: 0;
  z-index: 1000;
  height: var(--header-height);
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
}
.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}
.header__logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--font-size-xl);
  font-weight: 700;
  color: var(--color-white);
  text-decoration: none;
}
.header__logo:hover { color: var(--color-gold); }
.header__logo-icon { width: 32px; height: 32px; }
.header__nav { display: flex; align-items: center; gap: var(--space-1); }
.header__nav-link {
  padding: var(--space-2) var(--space-3);
  color: rgba(255,255,255,0.85);
  font-size: var(--font-size-sm);
  font-weight: 500;
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
  white-space: nowrap;
  text-decoration: none;
}
.header__nav-link:hover { color: var(--color-white); background: rgba(255,255,255,0.1); }
.header__nav-link--active { color: var(--color-white); background: rgba(255,255,255,0.15); font-weight: 600; }
.header__mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
  background: none;
  border: none;
  cursor: pointer;
}
.header__mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-white);
  border-radius: 1px;
  transition: transform var(--transition-base);
}

/* ===== Hero ===== */
.hero {
  background: var(--color-primary);
  color: var(--color-white);
  padding: var(--space-12) 0 var(--space-16);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 60%;
  height: 200%;
  background: radial-gradient(ellipse at center, rgba(0,107,228,0.15) 0%, transparent 70%);
  pointer-events: none;
}
.hero__content { position: relative; z-index: 1; }
.hero__title {
  font-size: var(--font-size-5xl);
  font-weight: 800;
  line-height: 1.1;
  margin-bottom: var(--space-3);
  color: var(--color-white);
}
.hero__subtitle {
  font-size: var(--font-size-xl);
  color: rgba(255,255,255,0.85);
  margin-bottom: var(--space-8);
}

/* Search Form */
.search-form {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  box-shadow: var(--shadow-xl);
}
.search-form__fields {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr auto;
  gap: var(--space-3);
  align-items: end;
}
.search-form__group { display: flex; flex-direction: column; gap: var(--space-1); }
.search-form__label {
  font-size: var(--font-size-xs);
  font-weight: 600;
  color: var(--color-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.search-form__input,
.search-form__select {
  padding: var(--space-3) var(--space-4);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  font-size: var(--font-size-sm);
  color: var(--color-text);
  background: var(--color-white);
  transition: border-color var(--transition-fast);
  min-height: 44px;
}
.search-form__input:focus,
.search-form__select:focus { border-color: var(--color-accent); outline: none; box-shadow: 0 0 0 3px rgba(0,108,228,0.1); }
.search-form__input::placeholder { color: var(--color-text-muted); }
.search-form__checkbox {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-top: var(--space-3);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  cursor: pointer;
}
.search-form__checkbox input[type="checkbox"] { width: 18px; height: 18px; accent-color: var(--color-accent); cursor: pointer; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  border-radius: var(--radius-md);
  font-size: var(--font-size-base);
  font-weight: 600;
  transition: all var(--transition-fast);
  white-space: nowrap;
  min-height: 44px;
  text-decoration: none;
}
.btn--primary { background: var(--color-accent); color: var(--color-white); }
.btn--primary:hover { background: var(--color-accent-hover); color: var(--color-white); }
.btn--gold { background: var(--color-gold); color: var(--color-primary); }
.btn--gold:hover { background: var(--color-gold-hover); }
.btn--outline { background: transparent; border: 1.5px solid var(--color-border); color: var(--color-text); }
.btn--outline:hover { border-color: var(--color-accent); color: var(--color-accent); }
.btn--white { background: var(--color-white); color: var(--color-primary); }
.btn--white:hover { background: var(--color-border-light); }
.btn--lg { padding: var(--space-4) var(--space-8); font-size: var(--font-size-lg); }
.btn--sm { padding: var(--space-2) var(--space-4); font-size: var(--font-size-sm); }
.btn--full { width: 100%; }

/* ===== Trust Badges ===== */
.trust-badges { background: var(--color-white); border-bottom: 1px solid var(--color-border); }
.trust-badges__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
}
.trust-badge { display: flex; gap: var(--space-4); align-items: flex-start; }
.trust-badge__icon {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  color: var(--color-accent);
}
.trust-badge__title { font-size: var(--font-size-sm); font-weight: 600; color: var(--color-text); margin-bottom: var(--space-1); }
.trust-badge__desc { font-size: var(--font-size-xs); color: var(--color-text-secondary); line-height: 1.4; }

/* ===== Offers ===== */
.offers__grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--space-6); }
.offer-card {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  display: flex;
  transition: box-shadow var(--transition-base);
}
.offer-card:hover { box-shadow: var(--shadow-lg); }
.offer-card__image {
  width: 200px;
  flex-shrink: 0;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
}
.offer-card__content { padding: var(--space-6); flex: 1; display: flex; flex-direction: column; justify-content: center; }
.offer-card__title { font-size: var(--font-size-xl); font-weight: 700; margin-bottom: var(--space-2); }
.offer-card__desc { font-size: var(--font-size-sm); color: var(--color-text-secondary); margin-bottom: var(--space-4); line-height: 1.5; }

/* ===== Property Types ===== */
.property-types__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: var(--space-3);
}
.property-type {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-4) var(--space-3);
  text-align: center;
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-text);
  cursor: pointer;
  transition: all var(--transition-fast);
}
.property-type:hover { border-color: var(--color-accent); color: var(--color-accent); box-shadow: var(--shadow-sm); }

/* ===== Trip Planner Tabs ===== */
.trip-planner { background: var(--color-white); }
.tabs { display: flex; gap: var(--space-1); overflow-x: auto; padding-bottom: var(--space-2); margin-bottom: var(--space-6); scrollbar-width: thin; }
.tabs::-webkit-scrollbar { height: 4px; }
.tabs::-webkit-scrollbar-thumb { background: var(--color-border); border-radius: 2px; }
.tab {
  padding: var(--space-2) var(--space-4);
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-md);
  white-space: nowrap;
  transition: all var(--transition-fast);
  cursor: pointer;
  border: 1px solid transparent;
  background: transparent;
  min-height: 36px;
}
.tab:hover { color: var(--color-text); background: var(--color-border-light); }
.tab--active { color: var(--color-accent); background: var(--color-primary-light); border-color: var(--color-accent); font-weight: 600; }
.tab-panel { display: none; }
.tab-panel--active { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: var(--space-4); animation: fadeIn 200ms ease; }

.destination-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.destination-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.destination-card__image {
  height: 140px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
}
.destination-card__info { padding: var(--space-3) var(--space-4); }
.destination-card__name { font-size: var(--font-size-sm); font-weight: 600; margin-bottom: var(--space-1); }
.destination-card__distance { font-size: var(--font-size-xs); color: var(--color-text-secondary); }

/* ===== Unique Properties Carousel ===== */
.carousel { position: relative; }
.carousel__viewport { overflow-x: auto; scroll-snap-type: x mandatory; scroll-behavior: smooth; -webkit-overflow-scrolling: touch; scrollbar-width: none; }
.carousel__viewport::-webkit-scrollbar { display: none; }
.carousel__track { display: flex; gap: var(--space-4); padding: var(--space-2) 0; }
.carousel__nav { position: absolute; top: 50%; transform: translateY(-50%); z-index: 10; width: 44px; height: 44px; border-radius: 50%; background: var(--color-white); border: 1px solid var(--color-border); box-shadow: var(--shadow-md); display: flex; align-items: center; justify-content: center; cursor: pointer; transition: all var(--transition-fast); color: var(--color-text); }
.carousel__nav:hover { box-shadow: var(--shadow-lg); border-color: var(--color-accent); }
.carousel__nav--prev { left: -20px; }
.carousel__nav--next { right: -20px; }
.carousel__nav:disabled { opacity: 0.4; cursor: default; }

.property-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.property-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
.property-card__image {
  height: 200px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
  position: relative;
}
.property-card__badge {
  position: absolute;
  top: var(--space-3);
  left: var(--space-3);
  background: var(--color-sale);
  color: white;
  font-size: var(--font-size-xs);
  font-weight: 700;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
}
.property-card__body { padding: var(--space-4); }
.property-card__name { font-size: var(--font-size-base); font-weight: 600; margin-bottom: var(--space-1); line-height: 1.3; }
.property-card__location { font-size: var(--font-size-xs); color: var(--color-text-secondary); margin-bottom: var(--space-2); }
.property-card__rating { display: flex; align-items: center; gap: var(--space-2); margin-bottom: var(--space-3); }
.property-card__score {
  background: var(--color-primary); color: white; font-size: var(--font-size-xs); font-weight: 700;
  padding: 2px 6px; border-radius: var(--radius-sm);
}
.property-card__score--good { background: #2563EB; }
.property-card__score--excellent { background: #16A34A; }
.property-card__score--wonderful { background: #7C3AED; }
.property-card__label { font-size: var(--font-size-xs); font-weight: 600; }
.property-card__reviews { font-size: var(--font-size-xs); color: var(--color-text-muted); }
.property-card__price { display: flex; align-items: baseline; gap: var(--space-1); }
.property-card__price-current { font-size: var(--font-size-xl); font-weight: 700; color: var(--color-text); }
.property-card__price-original { font-size: var(--font-size-sm); color: var(--color-text-muted); text-decoration: line-through; }
.property-card__price-unit { font-size: var(--font-size-xs); color: var(--color-text-secondary); }

/* ===== Trending ===== */
.trending__list { display: flex; gap: var(--space-3); flex-wrap: wrap; justify-content: center; }
.trending__tag {
  padding: var(--space-2) var(--space-5);
  border: 1px solid var(--color-border);
  border-radius: 9999px;
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-text);
  transition: all var(--transition-fast);
  cursor: pointer;
  background: var(--color-white);
}
.trending__tag:hover { border-color: var(--color-accent); color: var(--color-accent); background: var(--color-primary-light); }

/* ===== Explore Destinations ===== */
.explore__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-4);
}
.explore-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.explore-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.explore-card__image {
  height: 160px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
}
.explore-card__body { padding: var(--space-4); }
.explore-card__name { font-size: var(--font-size-base); font-weight: 600; margin-bottom: var(--space-1); }
.explore-card__count { font-size: var(--font-size-sm); color: var(--color-text-secondary); }

/* ===== Weekend Deals ===== */
.deals__grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: var(--space-4); }
.deal-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.deal-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
.deal-card__image {
  height: 180px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
  position: relative;
}
.deal-card__sale-badge {
  position: absolute;
  top: var(--space-3);
  right: var(--space-3);
  background: var(--color-sale);
  color: white;
  font-size: var(--font-size-xs);
  font-weight: 700;
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-sm);
}
.deal-card__body { padding: var(--space-4); }
.deal-card__name { font-size: var(--font-size-base); font-weight: 600; margin-bottom: var(--space-1); }
.deal-card__location { font-size: var(--font-size-xs); color: var(--color-text-secondary); margin-bottom: var(--space-2); }
.deal-card__meta { display: flex; justify-content: space-between; align-items: center; margin-bottom: var(--space-2); }
.deal-card__duration { font-size: var(--font-size-xs); color: var(--color-text-secondary); }
.deal-card__pricing { display: flex; align-items: baseline; gap: var(--space-2); }
.deal-card__original { font-size: var(--font-size-sm); color: var(--color-text-muted); text-decoration: line-through; }
.deal-card__sale { font-size: var(--font-size-2xl); font-weight: 700; color: var(--color-sale); }

/* ===== Homes Guests Love ===== */
.homes__grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: var(--space-4); }

/* ===== Loyalty CTA ===== */
.loyalty-cta {
  background: var(--color-primary);
  color: var(--color-white);
  text-align: center;
}
.loyalty-cta__inner {
  max-width: 600px;
  margin: 0 auto;
}
.loyalty-cta__title { font-size: var(--font-size-3xl); font-weight: 800; color: var(--color-white); margin-bottom: var(--space-2); }
.loyalty-cta__subtitle { font-size: var(--font-size-lg); color: var(--color-gold); font-weight: 600; margin-bottom: var(--space-3); }
.loyalty-cta__body { font-size: var(--font-size-base); color: rgba(255,255,255,0.85); margin-bottom: var(--space-6); }
.loyalty-cta__actions { display: flex; gap: var(--space-3); justify-content: center; }

/* ===== Popular Links Tabs ===== */
.popular-links { background: var(--color-white); }
.popular-links__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--space-3);
}
.popular-link {
  font-size: var(--font-size-sm);
  color: var(--color-accent);
  padding: var(--space-2) 0;
  transition: all var(--transition-fast);
  cursor: pointer;
}
.popular-link:hover { color: var(--color-accent-hover); }

/* ===== Benefits (Packages) ===== */
.benefits__grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-6); }
.benefit-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  text-align: center;
  transition: all var(--transition-base);
}
.benefit-card:hover { box-shadow: var(--shadow-md); }
.benefit-card__icon { width: 48px; height: 48px; color: var(--color-accent); margin: 0 auto var(--space-4); }
.benefit-card__title { font-size: var(--font-size-lg); font-weight: 700; margin-bottom: var(--space-2); }
.benefit-card__desc { font-size: var(--font-size-sm); color: var(--color-text-secondary); }

/* ===== Radio Group (Packages) ===== */
.radio-group { display: flex; gap: var(--space-2); flex-wrap: wrap; margin-bottom: var(--space-6); justify-content: center; }
.radio-option { position: relative; }
.radio-option input { position: absolute; opacity: 0; pointer-events: none; }
.radio-option label {
  display: block;
  padding: var(--space-3) var(--space-5);
  border: 1.5px solid var(--color-border);
  border-radius: 9999px;
  font-size: var(--font-size-sm);
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.radio-option input:checked + label { background: var(--color-primary-light); border-color: var(--color-accent); color: var(--color-accent); font-weight: 600; }
.radio-option input:focus-visible + label { outline: 2px solid var(--color-accent); outline-offset: 2px; }

/* ===== Rental Companies ===== */
.companies__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: var(--space-4);
}
.company-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-lg);
  font-weight: 700;
  color: var(--color-text-secondary);
  transition: all var(--transition-base);
  cursor: pointer;
  min-height: 80px;
}
.company-card:hover { border-color: var(--color-accent); color: var(--color-accent); box-shadow: var(--shadow-sm); }

/* ===== FAQ Accordion ===== */
.accordion { max-width: 800px; margin: 0 auto; }
.accordion__item { border-bottom: 1px solid var(--color-border); }
.accordion__trigger {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-5) 0;
  font-size: var(--font-size-base);
  font-weight: 600;
  color: var(--color-text);
  text-align: left;
  cursor: pointer;
  transition: color var(--transition-fast);
  background: none;
  border: none;
}
.accordion__trigger:hover { color: var(--color-accent); }
.accordion__trigger-icon {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition-base);
  color: var(--color-text-secondary);
}
.accordion__item--open .accordion__trigger-icon { transform: rotate(180deg); }
.accordion__content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}
.accordion__item--open .accordion__content { max-height: 300px; }
.accordion__body { padding: 0 0 var(--space-5) 0; font-size: var(--font-size-sm); color: var(--color-text-secondary); line-height: 1.6; }

/* ===== Credit Card Promo ===== */
.cc-promo {
  background: linear-gradient(135deg, var(--color-primary) 0%, #002266 100%);
  border-radius: var(--radius-2xl);
  padding: var(--space-10);
  color: var(--color-white);
  display: flex;
  align-items: center;
  gap: var(--space-10);
  max-width: 900px;
  margin: 0 auto;
}
.cc-promo__icon { width: 80px; height: 80px; flex-shrink: 0; color: var(--color-gold); }
.cc-promo__title { font-size: var(--font-size-2xl); font-weight: 700; color: var(--color-white); margin-bottom: var(--space-2); }
.cc-promo__body { font-size: var(--font-size-sm); color: rgba(255,255,255,0.8); margin-bottom: var(--space-4); }

/* ===== Destinations Table ===== */
.dest-table { width: 100%; max-width: 900px; margin: 0 auto; background: var(--color-white); border-radius: var(--radius-xl); overflow: hidden; border: 1px solid var(--color-border); }
.dest-table__row {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  padding: var(--space-4) var(--space-6);
  border-bottom: 1px solid var(--color-border-light);
  transition: background var(--transition-fast);
  cursor: pointer;
}
.dest-table__row:hover { background: var(--color-border-light); }
.dest-table__row--header { font-size: var(--font-size-xs); font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--color-text-secondary); background: var(--color-border-light); cursor: default; }
.dest-table__row--header:hover { background: var(--color-border-light); }
.dest-table__cell { font-size: var(--font-size-sm); display: flex; align-items: center; }
.dest-table__cell:first-child { font-weight: 600; color: var(--color-accent); }

/* ===== Recommended / Nearby (Attractions) ===== */
.attraction-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: var(--space-4); }
.attraction-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.attraction-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.attraction-card__image {
  height: 160px;
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
}
.attraction-card__body { padding: var(--space-4); }
.attraction-card__title { font-size: var(--font-size-base); font-weight: 600; margin-bottom: var(--space-1); line-height: 1.4; }
.attraction-card__meta { font-size: var(--font-size-xs); color: var(--color-text-secondary); display: flex; align-items: center; gap: var(--space-1); }

/* ===== Account CTA ===== */
.account-cta {
  background: var(--color-bg);
  border-radius: var(--radius-2xl);
  padding: var(--space-10);
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
}
.account-cta__title { font-size: var(--font-size-2xl); font-weight: 700; margin-bottom: var(--space-2); }
.account-cta__subtitle { font-size: var(--font-size-base); color: var(--color-text-secondary); margin-bottom: var(--space-3); }
.account-cta__body { font-size: var(--font-size-sm); color: var(--color-text-muted); margin-bottom: var(--space-6); }
.account-cta__actions { display: flex; gap: var(--space-3); justify-content: center; }

/* ===== Things to Do Tabs ===== */
.things-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-3);
}
.thing-link {
  font-size: var(--font-size-sm);
  color: var(--color-accent);
  padding: var(--space-2) 0;
  transition: all var(--transition-fast);
  cursor: pointer;
}
.thing-link:hover { color: var(--color-accent-hover); }

/* ===== Footer ===== */
.footer {
  background: var(--color-primary);
  color: rgba(255,255,255,0.8);
  padding: var(--space-16) 0 var(--space-8);
}
.footer__grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: var(--space-8); margin-bottom: var(--space-12); }
.footer__col-title { font-size: var(--font-size-sm); font-weight: 700; color: var(--color-white); margin-bottom: var(--space-4); }
.footer__link {
  display: block;
  font-size: var(--font-size-sm);
  color: rgba(255,255,255,0.7);
  padding: var(--space-1) 0;
  transition: color var(--transition-fast);
  text-decoration: none;
}
.footer__link:hover { color: var(--color-white); }
.footer__bottom {
  border-top: 1px solid rgba(255,255,255,0.15);
  padding-top: var(--space-8);
  text-align: center;
  font-size: var(--font-size-xs);
  color: rgba(255,255,255,0.6);
}

/* ===== Animations ===== */
@keyframes fadeIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .search-form__fields { grid-template-columns: 1fr 1fr; }
  .trust-badges__grid { grid-template-columns: repeat(2, 1fr); }
  .offers__grid { grid-template-columns: 1fr; }
  .offer-card { flex-direction: column; }
  .offer-card__image { width: 100%; height: 140px; }
  .footer__grid { grid-template-columns: repeat(3, 1fr); }
  .cc-promo { flex-direction: column; text-align: center; }
  .benefits__grid { grid-template-columns: 1fr; gap: var(--space-4); }
  .dest-table__row { grid-template-columns: 2fr 1fr 1fr; padding: var(--space-3) var(--space-4); }
}

@media (max-width: 768px) {
  :root { --header-height: 56px; }
  .hero__title { font-size: var(--font-size-3xl); }
  .hero__subtitle { font-size: var(--font-size-base); }
  .section { padding: var(--space-10) 0; }
  .section__title { font-size: var(--font-size-2xl); }
  .search-form__fields { grid-template-columns: 1fr; }
  .trust-badges__grid { grid-template-columns: 1fr; gap: var(--space-4); }
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
  .carousel__nav--prev { left: 8px; }
  .carousel__nav--next { right: 8px; }
  .dest-table__row { grid-template-columns: 1fr 1fr; padding: var(--space-3); }
  .dest-table__cell:last-child { display: none; }
  .header__nav { display: none; }
  .header__mobile-toggle { display: flex; }
  .header__nav--open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--header-height);
    left: 0;
    right: 0;
    background: var(--color-primary);
    padding: var(--space-4) var(--space-6);
    gap: var(--space-1);
    box-shadow: var(--shadow-lg);
  }
  .cc-promo { padding: var(--space-6); }
  .account-cta { padding: var(--space-6); }
}

@media (max-width: 480px) {
  .container { padding: 0 var(--space-4); }
  .section__title { font-size: var(--font-size-xl); }
  .footer__grid { grid-template-columns: 1fr; gap: var(--space-6); }
  .deals__grid,
  .homes__grid,
  .attraction-grid { grid-template-columns: 1fr; }
  .explore__grid { grid-template-columns: repeat(2, 1fr); }
  .loyalty-cta__actions { flex-direction: column; align-items: center; }
  .account-cta__actions { flex-direction: column; align-items: center; }
  .radio-group { flex-direction: column; align-items: stretch; }
  .radio-option label { text-align: center; }
}

@media (min-width: 769px) {
